[project]
name = "agentic-odi-mcp-server"
version = "0.1.0"
description = "FastMCP server for Agentic ODI."
requires-python = ">=3.10"
dependencies = [
    "fastmcp",
    "pydantic",
    "agentic-odi-core",
]

[tool.uv.sources]
agentic-odi-core = { workspace = true }

[project.scripts]
agentic-odi-server = "agentic_odi_mcp_server.mcp_server:main"
agentic-odi-mcp-server = "agentic_odi_mcp_server.mcp_server:main"

[build-system]
requires = ["hatchling"]
build-backend = "hatchling.build"

[tool.hatch.build.targets.wheel]
packages = ["src/agentic_odi_mcp_server"]

