+export const SETTINGS_PANEL: PanelDefinition = {
+  id: "settings",
+  label: "Settings",
+  title: "Settings",
+  blurb: "Point the studio at your model and your MCP bridge.",
+  icon: <SettingsIcon />,
+  render: () => <SettingsPanel />,
