+import { describe, expect, it } from "vitest";
+
+import {
+  greetingCandidates,
+  nextGreeting,
+  timeOfDayGreeting,
+  type GreetingContext,
+} from "./greeting";
+
+function context(overrides: Partial<GreetingContext> = {}): GreetingContext {
+  return {
+    now: new Date("2026-10-20T09:30:00"),
+    jobCount: 0,
+    outcomeCount: 0,
+    underservedCount: 0,
+    llmHealthy: true,
+    ...overrides,
+  };
+}
+
+describe("timeOfDayGreeting", () => {
+  it("greets the morning between 05:00 and 11:59", () => {
+    expect(timeOfDayGreeting(new Date("2026-10-20T05:00:00"))).toBe("Good morning");
+    expect(timeOfDayGreeting(new Date("2026-10-20T11:59:00"))).toBe("Good morning");
+  });
+
+  it("greets the afternoon between 12:00 and 17:59", () => {
+    expect(timeOfDayGreeting(new Date("2026-10-20T12:00:00"))).toBe("Good afternoon");
+    expect(timeOfDayGreeting(new Date("2026-10-20T17:59:00"))).toBe("Good afternoon");
+  });
+
+  it("greets the evening overnight", () => {
+    expect(timeOfDayGreeting(new Date("2026-10-20T18:00:00"))).toBe("Good evening");
+    expect(timeOfDayGreeting(new Date("2026-10-20T03:00:00"))).toBe("Good evening");
+  });
+});
+
+describe("greetingCandidates", () => {
+  it("leads with a plain greeting when no name is known", () => {
+    const [first] = greetingCandidates(context());
+    expect(first).toEqual({ id: "greeting", text: "Good morning", kind: "greeting" });
+  });
+
+  it("uses the display name when one is available", () => {
+    const [first] = greetingCandidates(context({ displayName: "  Ada  " }));
+    expect(first.text).toBe("Good morning, Ada");
+  });
+
+  it("reflects the opportunity landscape once outcomes exist", () => {
+    const insight = greetingCandidates(
+      context({ outcomeCount: 4, underservedCount: 1, jobCount: 2 }),
+    ).find((candidate) => candidate.id === "insight-outcomes");
+
+    expect(insight?.text).toBe("4 outcomes mapped — 1 underserved.");
+  });
+
+  it("stays honest about the canvas when nothing is underserved", () => {
+    const insight = greetingCandidates(context({ outcomeCount: 1 })).find(
+      (candidate) => candidate.id === "insight-outcomes",
+    );
+
+    expect(insight?.text).toBe("1 outcome mapped. Nothing is starving for attention.");
+  });
+
+  it("offers a capability line when the canvas is empty", () => {
+    const kinds = greetingCandidates(context()).map((candidate) => candidate.kind);
+    expect(kinds).toContain("capability");
+    expect(kinds).not.toContain("insight");
+  });
+
+  it("mentions local mode only when the model is unreachable", () => {
+    const offline = greetingCandidates(context({ llmHealthy: false }));
+    const online = greetingCandidates(context({ llmHealthy: true }));
+
+    expect(offline.some((candidate) => candidate.kind === "status")).toBe(true);
+    expect(online.some((candidate) => candidate.kind === "status")).toBe(false);
+  });
+});
+
+describe("nextGreeting", () => {
+  const candidates = greetingCandidates(context({ displayName: "Ada" }));
+
+  it("advances to the next candidate", () => {
+    expect(nextGreeting(candidates, candidates[0].id)?.id).toBe(candidates[1].id);
+  });
+
+  it("wraps around to the first headline", () => {
+    const last = candidates[candidates.length - 1];
+    expect(nextGreeting(candidates, last.id)?.id).toBe(candidates[0].id);
+  });
+
+  it("starts at the first headline when nothing is current", () => {
+    expect(nextGreeting(candidates, null)?.id).toBe(candidates[0].id);
+  });
+
+  it("returns null for an empty rotation", () => {
+    expect(nextGreeting([], "greeting")).toBeNull();
+  });
+});

Index: apps/studio/src/lib/greeting.ts
===================================================================
--- apps/studio/src/lib/greeting.ts	
+++ apps/studio/src/lib/greeting.ts	
@@ -0,0 +1,124 @@
+/**
+ * Headline copy for the conversational home screen.
+ *
+ * The hero line is the only "chrome" above the composer, so it has to earn its
+ * space: it greets when it knows who you are, reflects what is already on the
+ * canvas when there is data, and otherwise explains what the studio can do.
+ * The lines rotate so the surface feels alive rather than static.
+ */
+
+export interface GreetingContext {
+  now: Date;
+  displayName?: string | null;
+  jobCount: number;
+  outcomeCount: number;
+  underservedCount: number;
+  llmHealthy?: boolean | null;
+}
+
+export type GreetingKind = "greeting" | "insight" | "capability" | "status";
+
+export interface Greeting {
+  id: string;
+  text: string;
+  kind: GreetingKind;
+}
+
+/** Seconds between hero rotations. Exported so the UI and tests agree. */
+export const GREETING_ROTATION_MS = 7000;
+
+function cleanName(displayName?: string | null): string | null {
+  const trimmed = displayName?.trim();
+  if (!trimmed) {
+    return null;
+  }
+  return trimmed.replace(/\s+/g, " ");
+}
+
+export function timeOfDayGreeting(now: Date): string {
+  const hour = now.getHours();
+  if (hour >= 5 && hour < 12) {
+    return "Good morning";
+  }
+  if (hour >= 12 && hour < 18) {
+    return "Good afternoon";
+  }
+  return "Good evening";
+}
+
+function plural(count: number, one: string, many = `${one}s`): string {
+  return `${count} ${count === 1 ? one : many}`;
+}
+
+export function greetingCandidates(context: GreetingContext): Greeting[] {
+  const name = cleanName(context.displayName);
+  const greeting = timeOfDayGreeting(context.now);
+  const candidates: Greeting[] = [
+    {
+      id: "greeting",
+      text: name ? `${greeting}, ${name}` : greeting,
+      kind: "greeting",
+    },
+  ];
+
+  if (context.outcomeCount > 0) {
+    candidates.push({
+      id: "insight-outcomes",
+      text:
+        context.underservedCount > 0
+          ? `${plural(context.outcomeCount, "outcome")} mapped — ${context.underservedCount} underserved.`
+          : `${plural(context.outcomeCount, "outcome")} mapped. Nothing is starving for attention.`,
+      kind: "insight",
+    });
+  }
+
+  if (context.jobCount > 0) {
+    candidates.push({
+      id: "insight-jobs",
+      text:
+        context.jobCount === 1
+          ? "One job on the canvas. Want to break it into steps?"
+          : `${plural(context.jobCount, "job")} on the canvas. Want to break one into steps?`,
+      kind: "insight",
+    });
+  }
+
+  candidates.push(
+    {
+      id: "capability-job",
+      text: "What job should we get done today?",
+      kind: "capability",
+    },
+    {
+      id: "capability-friction",
+      text: "Tell me where your customers get stuck.",
+      kind: "capability",
+    },
+    {
+      id: "capability-outcomes",
+      text: "I turn complaints into measurable outcomes — then find the underserved ones.",
+      kind: "capability",
+    },
+  );
+
+  if (context.llmHealthy === false) {
+    candidates.push({
+      id: "status-offline",
+      text: "No model reachable right now. I can still walk you through the ODI playbook.",
+      kind: "status",
+    });
+  }
+
+  return candidates;
+}
+
+/**
+ * Pick the next headline in the rotation, never repeating the current one.
+ */
+export function nextGreeting(candidates: Greeting[], currentId?: string | null): Greeting | null {
+  if (!candidates.length) {
+    return null;
+  }
+  const currentIndex = candidates.findIndex((candidate) => candidate.id === currentId);
+  return candidates[(currentIndex + 1) % candidates.length];
+}

